---RefreshPlayerHeadNode
---@param gameObject UnityEngine.GameObject 配置 CommonPlayerHeadNode的游戏对象
---@param playerId number 玩家id
---@param info table   玩家信息
---@param excludeDialogs table 互斥弹窗列表
function PVPArenaUtils.RefreshPlayerHeadNode(gameObject, playerId, info, excludeDialogs, cb, isDisableCb)
    local PlayerHeadNodePath = "Game.Behaviours.CommonPlayerHeadNode"
    ---@type CommonPlayerHeadNode
    local env = CfUtils.GetLuaScr(gameObject, PlayerHeadNodePath)
    if not isNull(env) then
        playerId = checkInt(playerId)
        if not isDisableCb then
            env:SetCallBack(function ()
                ---头像的点击跳转事件
                if playerId <= 0 then
                    GameUtils.Toast(localize('该玩家暂未设置个人信息'))
                else
                    if cb then
                        cb()
                    else
                        PVPArenaUtils.ShowMatcherInfoDialog(playerId, info, excludeDialogs)
                    end
                end
            end)
        end
        env:FreshAvatarFrame(info.avatar, info.avatarFrame)
    end
end

