---GetRankTextBySeasonRank
---根据赛季排行获取排行文字
---@param seasonRank table
function PVPArenaUtils.GetRankTextBySeasonRank(seasonRank, playerId)
    local text
    if seasonRank then
        local maxRank = PVPArenaUtils.GetRankBySeasonRank(seasonRank, playerId)
        text = maxRank ~= nil and maxRank or "--"
    else
        text = "--"
    end
    return text
end

---GetRankBySeasonRank
---根据赛季排行获取排行
---@param seasonRank table 赛季排行
---@param playerId number 玩家id
function PVPArenaUtils.GetRankBySeasonRank(seasonRank, playerId)
    local rank
    if seasonRank then
        for i, rankData in ipairs(seasonRank) do
            local rankDataPlayerId = checkNumber(rankData.playerId)
            if rankDataPlayerId == playerId then
                rank = rankData.rank
                break
            end
        end
    end
    return rank
end

---CreateWinPlayerId2win
---最新比赛结果 生成 获胜玩家Id -> 是否获胜
---@param map table 对阵图站位数据
---@param curWheel number 当前再第几轮
---@param scope table 对阵图范围
function PVPArenaUtils.CreateWinPlayerId2win(map, curWheel, scope)
    local winPlayerId2win = {}

    --- 初始化当前轮的 比赛情况
    local oneWheelGroupScope = scope[curWheel - 1]
    if oneWheelGroupScope == nil then
        return winPlayerId2win
    end

    local leftBoundary, rightBoundary = SafeUnpack(oneWheelGroupScope)
    for position = leftBoundary, rightBoundary, 2 do
        local leftPositionData  = map[tostring(position)]
        local rightPositionData  = map[tostring(position + 1)]
        if leftPositionData and rightPositionData then
            local leftScore  = checkNumber(leftPositionData.score)
            local rightScore = checkNumber(rightPositionData.score)
            if leftScore ~= rightScore then
                local isLeftWin = leftScore > rightScore
                local playerId = isLeftWin and leftPositionData.playerId or rightPositionData.playerId
                winPlayerId2win[tostring(playerId)] = true
            end
        end
    end

    return winPlayerId2win
end

---CreateOneMatchChartData
---创建一个对阵图数据
---@param startPosition number  对阵图起始站位
---@param wheel number 该站位在第几轮
---@param isInBattle boolean 是否在战斗
---@param map table 对阵图站位数据   pvpArenaDojo.map
---@param matcherInfo table 比赛选手数据  pvpArenaDojo.matcherInfo
function PVPArenaUtils.CreateOneMatchChartData(startPosition, wheel, isInBattle, map, matcherInfo)
    local GetPlayerBaseData = function (position)
        local positionData  = map[tostring(position)]
        if positionData == nil then return end

        local playerId = positionData.playerId
        local score    = positionData.score
        local info     = matcherInfo[tostring(playerId)]
        return playerId, score, info
    end

    local CreateOneMatchChartData = function(position)
        local leftPlayerId, leftScore, leftInfo = GetPlayerBaseData(position)
        local rightPosition = position + 1
        local rightPlayerId, rightScore, rightInfo = GetPlayerBaseData(rightPosition)
        if not leftPlayerId and not rightPlayerId  then
            return
        end
        return {
            leftPlayerId  = checkNumber(leftPlayerId), --- 可能为0
            leftInfo      = leftInfo,                  --- 可能为nil
            leftScore     = leftScore,                 --- 可能为nil
            leftPosition  = position,
            rightPlayerId = checkNumber(rightPlayerId),--- 可能为0
            rightInfo     = rightInfo,                 --- 可能为nil
            rightScore    = rightScore,                --- 可能为nil
            rightPosition = rightPosition,
            positionWheel = wheel,
            inBattle = isInBattle and leftScore ~= nil and rightScore ~= nil and checkNumber(leftScore) == 0 and checkNumber(rightScore) == 0
        }
    end
    return CreateOneMatchChartData(startPosition)
end
