function PVPArenaUtils.InitMatchChartClickState(isAudience, isPlayerSelf, battleStatus, mainPanelStatus)

    local state
    ------------------------------------
    ---非参赛玩家
    ---进入投票界面 (投票界面自己细分状态)
    if isAudience then
        state = Constants.PVPArenaHeadNodeClickState.ShowQuizDialog
    ------------------------------------
    ---参赛玩家
    ---1. 参赛状态
    ---点击自己头像或编队按钮 进编队界面  点 非自己头像 进参赛记录
    ---2. 观赛状态（比赛失败）
    ---进参赛记录
    else
        --- 是玩家自己 并且 不是战斗准备状态 并且不是观赛状态
        if isPlayerSelf and battleStatus ~= Constants.PVPArenaBattleStatus.Prepare and mainPanelStatus ~= Constants.PVPArenaMainPanelStatus.WatchTheMatch then
            state = Constants.PVPArenaHeadNodeClickState.ShowFormationDialog
        else
            state = Constants.PVPArenaHeadNodeClickState.ShowMatcherInfoDialog
        end
    end

    return state
end

function PVPArenaUtils.ShowDialogByMatchChartState(state, oneMatchChartData, playerId, excludeDialogs)
    if state == Constants.PVPArenaHeadNodeClickState.ShowQuizDialog then
        PVPArenaUtils.ShowQuizDialog(oneMatchChartData, excludeDialogs)
    elseif state == Constants.PVPArenaHeadNodeClickState.ShowFormationDialog then
        PVPArenaUtils.ShowFormationDialog(excludeDialogs)
    elseif state == Constants.PVPArenaHeadNodeClickState.ShowMatcherInfoDialog then
        PVPArenaUtils.ShowMatcherInfoDialog(playerId, nil, excludeDialogs)
    end
end

---EnterBattle
---进入战斗
---@param env table
function PVPArenaUtils.EnterBattle(env)
    ---除了 战斗准备界面 其他的dialog全部清除
    local dialogs = UIModule.CurrentScreen.dialogs
    local count   = dialogs.Count
    for i = count - 1, 1 do
        local dialog = dialogs[i - 1]
        UIModule.CloseDialog(dialog)
    end

    FightPreWarMgr:GetInstance():FightEnter(Constants.SpecialQuestId.PVPArenaId, {loadingEnv = env})
end

