function PVPArenaUtils.VenueWorldPosition2VenueUIPosition(venuePosition, uiParent)
    ---@type UnityEngine.Camera
    local mainCamera = URPCameraController.mainCamera
    local screenPoint = mainCamera:WorldToScreenPoint(venuePosition)
    ---@type UnityEngine.Camera
    local uiCamera   = URPCameraController.uiCamera
    local v2 = Vector2.New(screenPoint.x, screenPoint.y)
    local _, vecNow = ScreenPointToLocalPointInRectangle(uiParent, v2, uiCamera)
    return vecNow
end

